import 'package:flutter/material.dart'; import '../services/preferences_service.dart'; import 'calculator_menu_screen.dart'; import 'tracker_screen.dart';
class HomeScreen extends StatefulWidget { const HomeScreen({super.key,required this.prefs,required this.onThemeChanged}); final PreferencesService prefs; final VoidCallback onThemeChanged; @override State<HomeScreen> createState()=>_HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen>{ int tab=0; @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Salary Tax & Expense Manager'),actions:[IconButton(icon:const Icon(Icons.settings),onPressed:()=>showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Settings'),content:SwitchListTile(title:const Text('Dark mode'),value:widget.prefs.darkMode,onChanged:(v) async {await widget.prefs.setDark(v); if(mounted){Navigator.pop(c);widget.onThemeChanged();}})))],),body:tab==0?const CalculatorMenuScreen():TrackerScreen(prefs:widget.prefs),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.calculate),label:'Calculators'),NavigationDestination(icon:Icon(Icons.account_balance_wallet),label:'Tracker')]),);}
}
